"""Background audio (e.g. office ambience) mixed into a voice call.

Configured per voice channel with a ``background_audio`` block next to
``asr`` / ``tts``. The audio loops under the agent's speech and, between
utterances, is streamed on its own at real-time pace.
"""

from __future__ import annotations

import asyncio
import audioop
import time
from pathlib import Path
from typing import Any, Awaitable, Callable, Dict, Optional

import miniaudio
import structlog
from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator

from rasa.core.channels.voice_stream.audio_bytes import (
    AudioEncoding,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.shared.exceptions import InvalidConfigException

structlogger = structlog.get_logger(__name__)

BUILT_IN_BACKGROUND_AUDIO_PATHS = {
    "office": Path(__file__).parent / "assets" / "office-background.mp3"
}
DEFAULT_BACKGROUND_AUDIO_LEVEL = 0.2

# Idle audio is sent in small chunks and kept only slightly ahead of playback, so
# agent speech that starts later never queues behind much background audio.
IDLE_CHUNK_SECONDS = 0.1
IDLE_LEAD_SECONDS = 0.2

_PCM16_SAMPLE_WIDTH = 2

SendAudio = Callable[[RasaAudioBytes], Awaitable[None]]


class BackgroundAudioConfig(BaseModel):
    """The ``background_audio`` block of a voice channel's configuration."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    source: str
    """Built-in audio name or local path of the audio file."""

    level: float = Field(default=DEFAULT_BACKGROUND_AUDIO_LEVEL, ge=0.0, le=1.0)
    """Gain applied to the background audio, from 0 (silent) to 1 (unchanged)."""

    @field_validator("source")
    @classmethod
    def validate_source(cls, source: str) -> str:
        """Reject sources that aren't a built-in name or existing local file."""
        if source not in BUILT_IN_BACKGROUND_AUDIO_PATHS and not Path(source).is_file():
            raise ValueError(
                f"`source` must be a built-in name "
                f"({', '.join(BUILT_IN_BACKGROUND_AUDIO_PATHS)}) or the path of an "
                f"existing local audio file, got '{source}'."
            )
        return source

    @property
    def audio_path(self) -> Path:
        """Returns the path of the audio file to play."""
        return BUILT_IN_BACKGROUND_AUDIO_PATHS.get(self.source, Path(self.source))


def parse_background_audio_config(
    raw_config: Optional[Dict[str, Any]],
) -> Optional[BackgroundAudioConfig]:
    """Returns the validated config, or `None` when the block is absent.

    Args:
        raw_config: The ``background_audio`` block from the channel credentials.

    Raises:
        InvalidConfigException: If the block has unknown keys or invalid values.
    """
    if raw_config is None:
        return None
    try:
        config = BackgroundAudioConfig.model_validate(raw_config)
    except ValidationError as error:
        raise InvalidConfigException(
            f"Invalid `background_audio` configuration: {error}"
        ) from error
    return config


class BackgroundAudioTrack:
    """Decoded background audio as mono PCM16 with the configured gain applied."""

    def __init__(self, pcm16: bytes) -> None:
        self._pcm16 = pcm16
        self._position = 0

    @property
    def is_empty(self) -> bool:
        """Test if the track contains no audio."""
        return not self._pcm16

    def read(self, num_bytes: int) -> bytes:
        """Returns the next `num_bytes` of looping audio."""
        chunks = []
        remaining = num_bytes
        while remaining > 0 and not self.is_empty:
            if self._position >= len(self._pcm16):
                self._position = 0
            chunk = self._pcm16[self._position : self._position + remaining]
            self._position += len(chunk)
            remaining -= len(chunk)
            chunks.append(chunk)
        return b"".join(chunks) + b"\x00" * remaining


class BackgroundAudioSource:
    """The configured audio file, decoded once per sample rate on first use."""

    def __init__(self, config: BackgroundAudioConfig) -> None:
        """Creates the source and checks the file is a decodable audio file.

        Raises:
            InvalidConfigException: If the file can't be read as audio.
        """
        self.config = config
        self._pcm16_by_sample_rate: Dict[int, bytes] = {}
        try:
            miniaudio.get_file_info(str(config.audio_path))
        except miniaudio.MiniaudioError as error:
            raise InvalidConfigException(
                f"`background_audio` file '{config.audio_path}' is not a supported "
                f"audio file: {error}"
            ) from error

    async def create_track(self, sample_rate: int) -> Optional[BackgroundAudioTrack]:
        """Returns a fresh track for one call, or `None` if decoding fails.

        Decoding runs in a worker thread so it doesn't block the event loop.
        A failure is logged and the call continues without background audio.
        """
        pcm16 = self._pcm16_by_sample_rate.get(sample_rate)
        if pcm16 is None:
            try:
                pcm16 = await asyncio.to_thread(self._decode, sample_rate)
            except miniaudio.MiniaudioError as error:
                structlogger.error(
                    "voice_channel.background_audio.decode_failed",
                    path=str(self.config.audio_path),
                    error=str(error),
                )
                return None
            self._pcm16_by_sample_rate[sample_rate] = pcm16
        return BackgroundAudioTrack(pcm16)

    def _decode(self, sample_rate: int) -> bytes:
        decoded = miniaudio.decode_file(
            str(self.config.audio_path),
            output_format=miniaudio.SampleFormat.SIGNED16,
            nchannels=1,
            sample_rate=sample_rate,
        )
        return audioop.mul(
            decoded.samples.tobytes(), _PCM16_SAMPLE_WIDTH, self.config.level
        )


class BackgroundAudioPlayer:
    """Plays one call's background audio under and between agent speech.

    Agent audio is mixed with the track as it is sent. While the agent is
    silent, an idle sender streams the track on its own, keeping at most
    ``IDLE_LEAD_SECONDS`` queued ahead of playback.
    """

    def __init__(
        self,
        track: BackgroundAudioTrack,
        audio_format: AudioFormat,
    ) -> None:
        self._track = track
        self._audio_format = audio_format
        self._is_agent_speaking = False
        # Monotonic time at which the caller will have heard everything we sent.
        self._queued_until = 0.0
        self._idle_task: Optional[asyncio.Task] = None

    @property
    def is_playing_idle_audio(self) -> bool:
        """Test if the idle sender should currently stream background audio."""
        return not self._is_agent_speaking and not self._track.is_empty

    def start(self, send: SendAudio) -> None:
        """Starts the idle sender."""
        self._idle_task = asyncio.create_task(
            self._run_idle_sender(send), name="background_audio"
        )

    async def stop(self) -> None:
        """Stops the idle sender."""
        if self._idle_task is not None:
            self._idle_task.cancel()
            await asyncio.gather(self._idle_task, return_exceptions=True)
            self._idle_task = None

    def mix_into(self, audio: RasaAudioBytes) -> RasaAudioBytes:
        """Returns agent audio with the background audio mixed in.

        Also marks the agent as speaking, which pauses the idle sender until
        `agent_finished_speaking` is called.
        """
        if not _is_supported_format(audio.format):
            return audio
        self._is_agent_speaking = True
        agent_pcm16 = audio.to_pcm16()
        background_pcm16 = self._track.read(len(agent_pcm16))
        mixed_pcm16 = audioop.add(agent_pcm16, background_pcm16, _PCM16_SAMPLE_WIDTH)
        self._extend_queued_audio(len(agent_pcm16), time.monotonic())
        return RasaAudioBytes(_from_pcm16(mixed_pcm16, audio.format), audio.format)

    def agent_finished_speaking(self) -> None:
        """Lets the idle sender resume after an agent utterance."""
        self._is_agent_speaking = False

    def playback_cleared(self) -> None:
        """Notes that the channel dropped the audio it had buffered (barge-in)."""
        self._queued_until = time.monotonic()

    def next_idle_chunk(self, now: float) -> Optional[RasaAudioBytes]:
        """Returns the next idle chunk to send, or `None` if none is due yet."""
        if (
            not self.is_playing_idle_audio
            or self._queued_until >= now + IDLE_LEAD_SECONDS
        ):
            return None
        num_bytes = int(IDLE_CHUNK_SECONDS * self._audio_format.sample_rate)
        num_bytes *= _PCM16_SAMPLE_WIDTH
        pcm16 = self._track.read(num_bytes)
        self._extend_queued_audio(len(pcm16), now)
        return RasaAudioBytes(
            _from_pcm16(pcm16, self._audio_format), self._audio_format
        )

    async def _run_idle_sender(self, send: SendAudio) -> None:
        if not _is_supported_format(self._audio_format):
            structlogger.warning(
                "voice_channel.background_audio.unsupported_format",
                audio_format=repr(self._audio_format),
            )
            return
        try:
            while True:
                chunk = self.next_idle_chunk(time.monotonic())
                if chunk is not None:
                    await send(chunk)
                    continue
                if self._track.is_empty:
                    return
                await asyncio.sleep(IDLE_CHUNK_SECONDS / 2)
        except Exception:
            structlogger.exception("voice_channel.background_audio.idle_sender_failed")

    def _extend_queued_audio(self, num_pcm16_bytes: int, now: float) -> None:
        duration = num_pcm16_bytes / (
            self._audio_format.sample_rate * _PCM16_SAMPLE_WIDTH
        )
        self._queued_until = max(self._queued_until, now) + duration


def _is_supported_format(audio_format: AudioFormat) -> bool:
    if audio_format.encoding == AudioEncoding.MULAW:
        return True
    return (
        audio_format.encoding == AudioEncoding.LINEAR and audio_format.bit_depth == 16
    )


def _from_pcm16(pcm16: bytes, audio_format: AudioFormat) -> bytes:
    if audio_format.encoding == AudioEncoding.MULAW:
        return audioop.lin2ulaw(pcm16, _PCM16_SAMPLE_WIDTH)
    return pcm16
